public class InnerPolicyGrantPolicyGrantPrincipalFactory(Action<Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal>
{

    internal InnerPolicyGrantGroupPolicyGrantPrincipalFactory GroupFactory { get; set; }

    internal InnerPolicyGrantProjectPolicyGrantPrincipalFactory ProjectFactory { get; set; }

    internal InnerPolicyGrantUserPolicyGrantPrincipalFactory UserFactory { get; set; }

    internal InnerPolicyGrantDomainUnitPolicyGrantPrincipalFactory DomainUnitFactory { get; set; }

    protected override Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal Create()
    {
        var policyGrantPrincipalResult = CreatePolicyGrantPrincipal();
        factoryAction?.Invoke(policyGrantPrincipalResult);

        return policyGrantPrincipalResult;
    }

    private Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal CreatePolicyGrantPrincipal()
    {
        var policyGrantPrincipalResult = new Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal();

        return policyGrantPrincipalResult;
    }
    public override void CreateChildren(Humidifier.DataZone.PolicyGrantTypes.PolicyGrantPrincipal result)
    {
        base.CreateChildren(result);

        result.Group ??= GroupFactory?.Build();
        result.Project ??= ProjectFactory?.Build();
        result.User ??= UserFactory?.Build();
        result.DomainUnit ??= DomainUnitFactory?.Build();
    }

} // End Of Class

